import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:flutter/foundation.dart';

// required: associates our `main.dart` with the code generated by Freezed
part 'collection.freezed.dart';
// optional: Since our Person class is serializable, we must add this line.
// But if Person was not serializable, we could skip it.

@freezed
class Collection with _$Collection {
  const factory Collection({
    required String title,
    required int id,
    required String image,
    required List<Collection> subCollections,
  }) = _Collection;
  factory Collection.fromJson(Map<String, dynamic> json) {
    List<Collection> subCollections = [];

    List subCollectionsJson =
        json.containsKey("children") && json["children"].isNotEmpty
            ? json["children"]
            : [];
    for (var element in subCollectionsJson) {
      subCollections.add(Collection.fromJson(element));
    }
    return Collection(
      title: json["title"],
      id: json["id"],
      image: json["thumbnail"],
      subCollections: subCollections,
    );
  }
}
// This file is "main.dart"
